    /*velocidad salida*/
    GPIOA->OSPEEDR &= ~(0b11<<5*2); /*pusimos la velocidad baja solo vamos a encender un led*/
    GPIOA->PUPDR &= ~(0b11<<5*2); /*pusimos no pull up ni pull down*/
    GPIOA->ODR &= ~ (0b1<<5);
    GPIOA->ODR |= (0b1<<5);


